import { describe, expect, it } from 'vitest'

import { progress } from '../../../../src/todos/application/progress'
import type { TodoViewModel } from '../../../../src/todos/application/TodoViewModel'

const todo = (id: string, status: TodoViewModel['status']): TodoViewModel => ({ id, title: id, status })

describe('progress', () => {
  it('should say there is nothing to do without todos', () => {
    expect(progress([])).toBe('Nothing to do')
  })

  it('should say all done when every todo is done', () => {
    expect(progress([todo('a', 'done'), todo('b', 'done')])).toBe('All done')
  })

  it('should count done todos out of the total', () => {
    expect(progress([todo('a', 'done'), todo('b', 'open'), todo('c', 'open')])).toBe('1 of 3 done')
  })

  it('should count zero done when all are open', () => {
    expect(progress([todo('a', 'open')])).toBe('0 of 1 done')
  })
})
